const store = { primary: 3000, canary: 8080 }

export async function readPort(name) {
  await new Promise((resolve) => setTimeout(resolve, 1))
  return store[name]
}

export async function readAll(names) {
  const out = []
  names.forEach(async (name) => {
    out.push(await readPort(name))
  })
  return out
}

import test from "node:test"
import assert from "node:assert/strict"
import { readAll } from "../src/ports.mjs"

test("readAll 等待全部端口", async () => {
  assert.deepEqual(await readAll(["primary", "canary"]), [3000, 8080])
})
